#!/usr/bin/env python3
from __future__ import annotations

import argparse
import json
import re
import shutil
import sys
from datetime import date, datetime, timezone
from pathlib import Path
from typing import Any


def slugify(value: str) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", value.strip().lower())
    slug = re.sub(r"-{2,}", "-", slug).strip("-")
    if not slug:
        raise ValueError("could not derive a slug from the provided value")
    return slug


def extract_json_summary(markdown: str) -> dict[str, Any] | None:
    blocks = re.findall(r"```json\s*(\{.*?\})\s*```", markdown, flags=re.DOTALL)
    for block in reversed(blocks):
        try:
            data = json.loads(block)
        except json.JSONDecodeError:
            continue
        if isinstance(data, dict) and "userStories" in data and "title" in data:
            return data
    return None


def extract_section(markdown: str, heading: str) -> str:
    pattern = re.compile(
        rf"^##\s+{re.escape(heading)}\s*$\n(?P<body>.*?)(?=^##\s+|\Z)",
        flags=re.MULTILINE | re.DOTALL,
    )
    match = pattern.search(markdown)
    return match.group("body").strip() if match else ""


def parse_story_blocks(markdown: str) -> list[dict[str, Any]]:
    section = extract_section(markdown, "User Stories")
    if not section:
        return []

    matches = list(re.finditer(r"^###\s+(?:(US-\d+):\s+)?(.+)$", section, flags=re.MULTILINE))
    stories: list[dict[str, Any]] = []

    for index, match in enumerate(matches, start=1):
        start = match.end()
        end = matches[index].start() if index < len(matches) else len(section)
        block = section[start:end].strip()

        title = match.group(2).strip()
        story_id = match.group(1) or f"US-{index:03d}"

        description_match = re.search(r"\*\*Description:\*\*\s*(.+)", block)
        if not description_match:
            raise ValueError(f"story {story_id} is missing a '**Description:**' line")
        description = description_match.group(1).strip()

        criteria_match = re.search(r"\*\*Acceptance Criteria:\*\*(?P<body>.*)", block, flags=re.DOTALL)
        if not criteria_match:
            raise ValueError(f"story {story_id} is missing an '**Acceptance Criteria:**' section")

        criteria: list[str] = []
        for line in criteria_match.group("body").splitlines():
            stripped = line.strip()
            if not stripped:
                continue
            if stripped.startswith("### "):
                break
            if stripped.startswith("- [ ] "):
                criteria.append(stripped[6:].strip())
            elif stripped.startswith("- "):
                criteria.append(stripped[2:].strip())

        if not criteria:
            raise ValueError(f"story {story_id} does not have any list-form acceptance criteria")

        stories.append(
            {
                "id": story_id,
                "title": title,
                "description": description,
                "acceptanceCriteria": criteria,
            }
        )

    return stories


def parse_markdown_prd(path: Path) -> dict[str, Any]:
    markdown = path.read_text(encoding="utf-8-sig")
    summary = extract_json_summary(markdown)

    title_match = re.search(r"^#\s+(?:PRD:\s+)?(.+)$", markdown, flags=re.MULTILINE)
    if not title_match:
        raise ValueError("markdown PRD is missing a top-level title")
    title = title_match.group(1).strip()

    introduction = extract_section(markdown, "Introduction / Overview") or extract_section(markdown, "Introduction")

    if summary:
        user_stories = summary.get("userStories")
        if not isinstance(user_stories, list) or not user_stories:
            raise ValueError("JSON summary must include at least one user story")
        return {
            "title": summary.get("title", title),
            "description": introduction or title,
            "userStories": user_stories,
            "prdId": summary.get("prdId"),
        }

    stories = parse_story_blocks(markdown)
    if not stories:
        raise ValueError("markdown PRD does not contain any parsable user stories")

    return {
        "title": title,
        "description": introduction or title,
        "userStories": stories,
        "prdId": None,
    }


def normalize_story(raw_story: dict[str, Any], index: int) -> dict[str, Any]:
    title = raw_story.get("title")
    description = raw_story.get("description")
    criteria = raw_story.get("acceptanceCriteria") or raw_story.get("acceptance_criteria")

    if not isinstance(title, str) or not title.strip():
        raise ValueError(f"user story {index} is missing a title")
    if not isinstance(description, str) or not description.strip():
        raise ValueError(f"user story {index} is missing a description")
    if not isinstance(criteria, list) or not all(isinstance(item, str) and item.strip() for item in criteria):
        raise ValueError(f"user story {index} must define a non-empty acceptance criteria list")

    normalized_criteria = [item.strip() for item in criteria]
    if not any(item.lower() == "typecheck passes" for item in normalized_criteria):
        normalized_criteria.append("Typecheck passes")

    return {
        "id": f"US-{index:03d}",
        "title": title.strip(),
        "description": description.strip(),
        "acceptanceCriteria": normalized_criteria,
        "priority": index,
        "passes": False,
        "notes": "",
    }


def progress_has_meaningful_content(path: Path) -> bool:
    if not path.exists():
        return False

    content = path.read_text(encoding="utf-8-sig")
    meaningful_lines = []
    for line in content.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if stripped == "# Ralph Progress Log":
            continue
        if stripped.startswith("Started:"):
            continue
        if stripped == "---":
            continue
        meaningful_lines.append(stripped)
    return bool(meaningful_lines)


def write_progress_header(path: Path) -> None:
    timestamp = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
    path.write_text(f"# Ralph Progress Log\nStarted: {timestamp}\n---\n", encoding="utf-8")


def archive_existing_run(output_path: Path, progress_path: Path, new_branch: str) -> None:
    if not output_path.exists():
        return

    try:
        current_data = json.loads(output_path.read_text(encoding="utf-8-sig"))
    except json.JSONDecodeError as exc:
        raise ValueError(f"existing output is not valid JSON: {output_path}") from exc

    current_branch = current_data.get("branchName")
    if not isinstance(current_branch, str) or not current_branch.strip():
        return

    if current_branch == new_branch:
        return

    if not progress_has_meaningful_content(progress_path):
        return

    archive_name = f"{date.today().isoformat()}-{slugify(current_branch.replace('ralph/', ''))}"
    archive_dir = output_path.parent / "archive" / archive_name
    archive_dir.mkdir(parents=True, exist_ok=True)

    shutil.copy2(output_path, archive_dir / output_path.name)
    if progress_path.exists():
        shutil.copy2(progress_path, archive_dir / progress_path.name)

    write_progress_header(progress_path)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Convert a markdown PRD into Ralph's prd.json format.")
    parser.add_argument("prd_path", help="Path to the markdown PRD file.")
    parser.add_argument(
        "--project",
        help="Project name for the Ralph config. Defaults to the current working directory name.",
    )
    parser.add_argument(
        "--branch-name",
        help="Override the Ralph branch name. Defaults to ralph/<feature-name> derived from the PRD.",
    )
    parser.add_argument(
        "--output",
        "-o",
        default="prd.json",
        help="Output path for prd.json. Defaults to ./prd.json.",
    )
    parser.add_argument(
        "--progress-file",
        help="Path to progress.txt. Defaults to <output directory>/progress.txt.",
    )
    parser.add_argument(
        "--archive-existing",
        action="store_true",
        help="Archive an existing prd.json when it belongs to a different branch and progress.txt has content.",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    prd_path = Path(args.prd_path)
    output_path = Path(args.output)
    progress_path = Path(args.progress_file) if args.progress_file else output_path.with_name("progress.txt")

    try:
        parsed = parse_markdown_prd(prd_path)
        project = args.project or Path.cwd().name
        slug_source = (parsed.get("prdId") or parsed["title"]).removeprefix("prd-")
        branch_name = args.branch_name or f"ralph/{slugify(slug_source)}"
        stories = [normalize_story(raw_story, index) for index, raw_story in enumerate(parsed["userStories"], start=1)]

        if output_path.exists() and not args.archive_existing:
            try:
                current_data = json.loads(output_path.read_text(encoding="utf-8-sig"))
            except json.JSONDecodeError:
                current_data = {}
            current_branch = current_data.get("branchName")
            if isinstance(current_branch, str) and current_branch and current_branch != branch_name and progress_has_meaningful_content(progress_path):
                print(
                    "error: existing prd.json belongs to a different branch and progress.txt has content; "
                    "rerun with --archive-existing",
                    file=sys.stderr,
                )
                return 1

        if args.archive_existing:
            archive_existing_run(output_path, progress_path, branch_name)

        output_path.parent.mkdir(parents=True, exist_ok=True)
        result = {
            "project": project,
            "branchName": branch_name,
            "description": parsed["description"],
            "userStories": stories,
        }
        output_path.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

        if not progress_path.exists():
            write_progress_header(progress_path)

        print(f"created {output_path}")
        return 0
    except (OSError, ValueError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""
Quick validation script for skills - minimal version
"""

import sys
import os
import re
import yaml
from pathlib import Path


def strip_markdown_code(text):
    """Blank fenced/inline code so markdown link parsing ignores examples while keeping line numbers."""
    def blank(match):
        return re.sub(r"[^\n]", " ", match.group(0))

    text = re.sub(r"```[\s\S]*?```", blank, text)
    text = re.sub(r"~~~[\s\S]*?~~~", blank, text)
    text = re.sub(r"`[^`\n]*`", blank, text)
    return text


def split_markdown_destination(raw):
    """Extract link target and optional title from markdown destination."""
    value = raw.strip()
    if not value:
        return "", None

    if value.startswith("<"):
        closing = value.find(">")
        if closing > 0:
            target = value[1:closing].strip()
            title = value[closing + 1 :].strip() or None
            return target, title

    match = re.match(r'^(\S+)(?:\s+(?:"([^"]*)"|\'([^\']*)\'|\(([^)]*)\)))?$', value)
    if not match:
        return value, None

    target = (match.group(1) or "").strip()
    title = (match.group(2) or match.group(3) or match.group(4) or "").strip() or None
    return target, title


def normalize_local_target(target):
    """Strip fragment/query from a local markdown link target."""
    value = target.strip()
    hash_index = value.find("#")
    if hash_index >= 0:
        value = value[:hash_index]
    query_index = value.find("?")
    if query_index >= 0:
        value = value[:query_index]
    return value.strip()


def parse_markdown_links(text):
    """Return markdown links with text/target/title/line info."""
    sanitized = strip_markdown_code(text)
    link_re = re.compile(r'!?\[([^\]\n]*?)\]\(([^)\n]+)\)')
    links = []
    for match in link_re.finditer(sanitized):
        if match.group(0).startswith("!"):
            continue
        target, title = split_markdown_destination(match.group(2))
        if not target:
            continue
        line = sanitized.count("\n", 0, match.start()) + 1
        links.append({
            "text": (match.group(1) or "").strip(),
            "target": target,
            "title": title,
            "line": line,
        })
    return links


def format_link_label(link):
    """Prefer visible link text in diagnostics."""
    if link["text"]:
        return f'"{link["text"]}"'
    if link["title"]:
        return f'"{link["title"]}"'
    return link["target"]


def normalize_whitelist_entry(value):
    """Normalize whitelist entries to stable posix-like relative paths."""
    normalized = str(value).strip().replace("\\", "/")
    if normalized.startswith("./"):
        normalized = normalized[2:]
    return normalized


def is_skippable_link(target):
    """Skip external or same-file links."""
    if target.startswith("#"):
        return True
    if target.startswith("http://") or target.startswith("https://"):
        return True
    if target.startswith("mailto:"):
        return True
    if re.match(r"^[a-zA-Z]+://", target):
        return True
    return False


def is_path_whitelisted(relative_target, whitelist):
    """Match exact whitelist entries or prefix entries ending with slash."""
    normalized_target = normalize_whitelist_entry(relative_target)
    for rule in whitelist:
        normalized_rule = normalize_whitelist_entry(rule)
        if not normalized_rule:
            continue
        if normalized_rule.endswith("/"):
            prefix = normalized_rule[:-1]
            if normalized_target == prefix or normalized_target.startswith(normalized_rule):
                return True
            continue
        if normalized_target == normalized_rule:
            return True
    return False


def validate_skill(skill_path):
    """Basic validation of a skill"""
    skill_path = Path(skill_path)

    # Check SKILL.md exists
    skill_md = skill_path / "SKILL.md"
    if not skill_md.exists():
        return False, "SKILL.md not found"

    # Read and validate frontmatter
    content = skill_md.read_text(encoding="utf-8-sig")
    if not content.startswith("---"):
        return False, "No YAML frontmatter found"

    # Extract frontmatter
    match = re.match(r"^---\n(.*?)\n---", content, re.DOTALL)
    if not match:
        return False, "Invalid frontmatter format"

    frontmatter_text = match.group(1)

    # Parse YAML frontmatter
    try:
        frontmatter = yaml.safe_load(frontmatter_text)
        if not isinstance(frontmatter, dict):
            return False, "Frontmatter must be a YAML dictionary"
    except yaml.YAMLError as e:
        return False, f"Invalid YAML in frontmatter: {e}"

    errors = []

    # Define allowed properties
    ALLOWED_PROPERTIES = {"name", "description", "license", "allowed-tools", "metadata", "triggers", "tools", "related"}

    # Check for unexpected properties (excluding nested keys under metadata)
    unexpected_keys = set(frontmatter.keys()) - ALLOWED_PROPERTIES
    if unexpected_keys:
        return False, (
            f"Unexpected key(s) in SKILL.md frontmatter: {', '.join(sorted(unexpected_keys))}. "
            f"Allowed properties are: {', '.join(sorted(ALLOWED_PROPERTIES))}"
        )

    # Check required fields
    if "name" not in frontmatter:
        return False, "Missing 'name' in frontmatter"
    if "description" not in frontmatter:
        return False, "Missing 'description' in frontmatter"

    metadata = frontmatter.get("metadata")
    link_whitelist = []
    if metadata is not None:
        if not isinstance(metadata, dict):
            return False, "metadata must be a mapping if provided"
        allowed_metadata_properties = {"triggers", "tools", "related", "languages", "frameworks", "roles", "scenarios", "workspace_scope", "link_whitelist"}
        unexpected_metadata_keys = set(metadata.keys()) - allowed_metadata_properties
        if unexpected_metadata_keys:
            return False, (
                f"Unexpected key(s) in metadata: {', '.join(sorted(unexpected_metadata_keys))}. "
                f"Allowed metadata keys are: {', '.join(sorted(allowed_metadata_properties))}"
            )
        raw_whitelist = metadata.get("link_whitelist", [])
        if raw_whitelist is None:
            raw_whitelist = []
        if not isinstance(raw_whitelist, list) or any(not isinstance(item, str) or not item.strip() for item in raw_whitelist):
            return False, "metadata.link_whitelist must be a list of non-empty strings"
        link_whitelist = [normalize_whitelist_entry(item) for item in raw_whitelist if normalize_whitelist_entry(item)]

    # Extract name for validation
    name = frontmatter.get("name", "")
    if not isinstance(name, str):
        return False, f"Name must be a string, got {type(name).__name__}"
    name = name.strip()
    if name:
        # Check naming convention (hyphen-case: lowercase with hyphens)
        if not re.match(r"^[a-z0-9-]+$", name):
            return False, f"Name '{name}' should be hyphen-case (lowercase letters, digits, and hyphens only)"
        if name.startswith("-") or name.endswith("-") or "--" in name:
            return False, f"Name '{name}' cannot start/end with hyphen or contain consecutive hyphens"
        # Check name length (max 64 characters per spec)
        if len(name) > 64:
            return False, f"Name is too long ({len(name)} characters). Maximum is 64 characters."

    # Extract and validate description
    description = frontmatter.get("description", "")
    if not isinstance(description, str):
        return False, f"Description must be a string, got {type(description).__name__}"
    description = description.strip()
    if description:
        # Check for angle brackets
        if "<" in description or ">" in description:
            return False, "Description cannot contain angle brackets (< or >)"
        # Check description length (max 1024 characters per spec)
        if len(description) > 1024:
            return False, f"Description is too long ({len(description)} characters). Maximum is 1024 characters."

    skill_root = skill_path.resolve()
    markdown_files = sorted(
        file_path
        for file_path in skill_root.rglob("*.md")
        if "__pycache__" not in file_path.parts
    )

    for markdown_file in markdown_files:
        rel_markdown = markdown_file.relative_to(skill_root).as_posix()
        content = markdown_file.read_text(encoding="utf-8-sig")

        if len(re.findall(r"^```", content, re.MULTILINE)) % 2 != 0:
            errors.append(f"{rel_markdown}: unclosed code fence detected (``` count is odd)")
        if len(re.findall(r"^~~~", content, re.MULTILINE)) % 2 != 0:
            errors.append(f"{rel_markdown}: unclosed code fence detected (~~~ count is odd)")

        for link in parse_markdown_links(content):
            local_target = normalize_local_target(link["target"])
            if not local_target or is_skippable_link(local_target):
                continue
            if local_target.startswith("/"):
                continue
            if os.path.isabs(local_target):
                continue

            resolved = (markdown_file.parent / local_target).resolve()
            if not resolved.exists():
                errors.append(
                    f'{rel_markdown}: line {link["line"]} link {format_link_label(link)} target not found: {local_target}'
                )
                continue

            if not (resolved == skill_root or skill_root in resolved.parents):
                escaped_relative = normalize_whitelist_entry(os.path.relpath(resolved, skill_root))
                if not is_path_whitelisted(escaped_relative, link_whitelist):
                    errors.append(
                        f'{rel_markdown}: line {link["line"]} link {format_link_label(link)} points outside skill root: '
                        f'{escaped_relative} (allow via metadata.link_whitelist if intentional)'
                    )

    if errors:
        preview = "\n".join(f"- {item}" for item in errors[:10])
        if len(errors) > 10:
            preview += f"\n- ... and {len(errors) - 10} more"
        return False, f"Skill validation failed:\n{preview}"

    return True, "Skill is valid!"


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python quick_validate.py <skill_directory>")
        sys.exit(1)

    valid, message = validate_skill(sys.argv[1])
    print(message)
    sys.exit(0 if valid else 1)

# Store Design

Use this reference when the task is about store boundaries, state normalization, or Pinia design patterns.

## Single Responsibility

```typescript
const useUserStore = defineStore('user', { /* user domain */ });
const useUIStore = defineStore('ui', { /* ui state */ });
const useCartStore = defineStore('cart', { /* cart state */ });
```

Avoid one giant store that mixes user data, UI state, notifications, products, and workflow logic.

## Normalized State

```typescript
interface NormalizedState {
  posts: Record<number, Post>;
  users: Record<number, User>;
  comments: Record<number, Comment>;
  postIds: number[];
}
```

Normalize when collections are large, nested, or updated independently.

## Pinia Setup Store

```typescript
export const useCounterStore = defineStore('counter', () => {
  const count = ref(0);
  const doubleCount = computed(() => count.value * 2);

  function increment() {
    count.value++;
  }

  return { count, doubleCount, increment };
});
```

## Cross-Store Coordination

```typescript
export const useCheckoutStore = defineStore('checkout', () => {
  const userStore = useUserStore();
  const cartStore = useCartStore();
  const canCheckout = computed(() => userStore.isLoggedIn && cartStore.itemCount > 0);
  return { canCheckout };
});
```

## Common Pitfalls

- Resolve cyclic dependencies by acquiring other stores inside actions.
- Use `storeToRefs()` when destructuring reactive values from a store.
- Keep API orchestration close to the domain store, not spread across components.

