{
  "id": "micro",
  "version": "1.0.0",
  "name": "Micro Workflow (3-step fast loop)",
  "description": "Lightweight 3-step workflow for hotfixes, single-file changes, and small tasks: plan -> implement -> verify. No review or separate build-fix step.",
  "steps": [
    {
      "id": "plan",
      "type": "create_taskbook",
      "title": "Quick plan (inline task decomposition)",
      "description": "Create a minimal TaskBook with 1-3 tasks. Skip PRD and deep analysis — rely on user context and quick file scan.",
      "toolHints": {
        "recommended": [
          "agent:planner",
          "human"
        ]
      },
      "outputs": {
        "taskbook": ".codebuddy/taskbooks/active/tb-*.json"
      }
    },
    {
      "id": "implement",
      "type": "tdd_implement",
      "title": "Implement with inline smoke",
      "description": "Execute tasks using TDD or direct implementation. Run smoke test after each task.",
      "gates": [
        "smoke_passed"
      ],
      "toolHints": {
        "recommended": [
          "agent:tdd-driver",
          "agent:build-fix",
          "shell:npm test"
        ]
      }
    },
    {
      "id": "verify",
      "type": "acceptance_and_archive",
      "title": "Verify & close",
      "description": "Run full build, confirm tests pass, archive TaskBook. No formal review — user accepts inline.",
      "gates": [
        "full_passed"
      ],
      "toolHints": {
        "recommended": [
          "shell:npm run build",
          "shell:npm test",
          "human"
        ]
      }
    }
  ],
  "edges": [
    { "from": "plan", "to": "implement" },
    { "from": "implement", "to": "verify" }
  ],
  "gates": [
    {
      "id": "smoke_passed",
      "type": "checks",
      "title": "Smoke tests passed",
      "required": true,
      "params": {
        "budgetMinutes": 3,
        "commands": ["npm test"]
      }
    },
    {
      "id": "full_passed",
      "type": "checks",
      "title": "Full build passed",
      "required": true,
      "params": {
        "budgetMinutes": 10,
        "commands": ["npm run build"],
        "npmScripts": ["test"],
        "failIfMissing": false
      }
    }
  ],
  "policies": {
    "concurrency": {
      "maxParallelTasks": 1,
      "conflictStrategy": "deny_same_file_set"
    },
    "blocking": {
      "onGateFail": "blocked",
      "requiresHumanToUnblock": false
    },
    "buildFix": {
      "maxRounds": 2,
      "retryFromStep": "implement",
      "escalateToHuman": true
    }
  }
}

{
  "id": "sprint",
  "version": "1.0.0",
  "name": "Sprint Workflow (5-step feature loop)",
  "description": "Mid-weight 5-step workflow for feature sprints and moderate refactoring: analyze -> plan -> TDD implement (batched) -> review -> acceptance. Skips PRD generation and separate build-fix step.",
  "steps": [
    {
      "id": "analyze",
      "type": "analyze_project",
      "title": "Analyze project structure/modules",
      "description": "Generate architecture/module reports to support planning and impact analysis.",
      "toolHints": {
        "recommended": [
          "script:structure-analyzer",
          "script:module-mapper"
        ]
      },
      "outputs": {
        "reports": [
          ".codebuddy/reports/architecture/latest.json",
          ".codebuddy/reports/modules/latest.json"
        ]
      }
    },
    {
      "id": "plan",
      "type": "create_taskbook",
      "title": "Create TaskBook (tasks + acceptance criteria)",
      "description": "Break requirements into executable tasks with dependencies and acceptance criteria.",
      "toolHints": {
        "recommended": [
          "agent:planner",
          "script:taskbook-manager"
        ]
      },
      "outputs": {
        "taskbook": ".codebuddy/taskbooks/active/tb-*.json"
      }
    },
    {
      "id": "tdd_implement",
      "type": "tdd_implement",
      "title": "Test-first implementation (TDD batched)",
      "description": "Execute tasks using TDD cycle (RED->GREEN->REFACTOR) in batches. Includes inline build-fix: on failure, auto-diagnose up to 3 rounds before escalating.",
      "gates": [
        "contracts_valid",
        "smoke_passed"
      ],
      "toolHints": {
        "recommended": [
          "agent:tdd-driver",
          "agent:build-fix",
          "human"
        ]
      }
    },
    {
      "id": "review",
      "type": "code_review",
      "title": "Code review gate",
      "description": "Perform code review. Security and performance reviews are optional add-ons.",
      "gates": [
        "review_passed"
      ],
      "toolHints": {
        "recommended": [
          "agent:code-reviewer",
          "human"
        ]
      }
    },
    {
      "id": "acceptance",
      "type": "acceptance_and_archive",
      "title": "Acceptance & Archive",
      "description": "Run full build, generate acceptance report, archive TaskBook to history.",
      "gates": [
        "full_passed"
      ],
      "toolHints": {
        "recommended": [
          "script:taskbook-manager",
          "human"
        ]
      }
    }
  ],
  "edges": [
    { "from": "analyze", "to": "plan" },
    { "from": "plan", "to": "tdd_implement" },
    { "from": "tdd_implement", "to": "review" },
    { "from": "review", "to": "acceptance" }
  ],
  "gates": [
    {
      "id": "contracts_valid",
